def min_partition_sum(n, c, a):
    if c == 1:
        return sum(a)

    total_sum = sum(a)
    result = float('inf')
    prefix_sum = [0]

    for num in a:
        prefix_sum.append(prefix_sum[-1] + num)

    for i in range(1, n + 1):
        for j in range(i, n + 1, c):
            k = j - i
            value = prefix_sum[j] - prefix_sum[i] - (k // c * min(a[i:j]))
            result = min(result, value)

    return result

# Read input
n, c = map(int, input().split())
a = list(map(int, input().split()))

# Output result
print(min_partition_sum(n, c, a))
